const items = $input.all();
const result = [];
for (const item of items) {
  try {
    const data = item.json;
    const rssRoot = data.rss || data;
    const channel = rssRoot.channel;
    if (!channel) continue;
    const jobs = Array.isArray(channel.item) ? channel.item : (channel.item ? [channel.item] : []);
    for (const job of jobs) {
      if (!job) continue;
      const title = typeof job.title === 'string' ? job.title : (job.title?._ || '');
      const link = typeof job.link === 'string' ? job.link : (job.guid?._ || job.guid || '');
      const desc = typeof job.description === 'string' ? job.description : (job.description?._ || '');
      const cleanDesc = desc.replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim().substring(0, 3000);
      if (!link) continue;
      result.push({ json: {
        job_title: title.trim(),
        company: (job['job:company'] || '').trim(),
        job_url: link.trim(),
        source: 'RemoteOK',
        location_text: job['job:location'] || 'Worldwide',
        salary: job['job:salary'] || '',
        description: cleanDesc,
        posted_date: job.pubDate || new Date().toISOString(),
        tags: Array.isArray(job.category) ? job.category.join(', ') : (job.category || ''),
        job_id: link.trim()
      }});
    }
  } catch(e) { console.log('RemoteOK parse error:', e.message); }
}
return result.length > 0 ? result : [];

