// Wellfound uses JavaScript-rendered content; extract JSON-LD or structured data if available
const items = $input.all();
const result = [];
for (const item of items) {
  try {
    const html = typeof item.json.data === 'string' ? item.json.data : JSON.stringify(item.json);
    // Extract JSON-LD blocks
    const jsonLdMatches = html.matchAll(/<script[^>]*type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/gi);
    for (const match of jsonLdMatches) {
      try {
        const ld = JSON.parse(match[1]);
        if (ld['@type'] === 'JobPosting') {
          result.push({ json: {
            job_title: ld.title || '',
            company: ld.hiringOrganization?.name || '',
            job_url: ld.url || ld.sameAs || '',
            source: 'Wellfound',
            location_text: ld.jobLocation?.address?.addressRegion || ld.applicantLocationRequirements?.name || 'Worldwide',
            salary: ld.baseSalary?.value?.value || '',
            description: (ld.description || '').replace(/<[^>]*>/g, ' ').substring(0, 3000),
            posted_date: ld.datePosted || new Date().toISOString(),
            tags: ld.occupationalCategory || '',
            job_id: ld.url || ld.sameAs || ''
          }});
        }
      } catch(pe) {}
    }
  } catch(e) { console.log('Wellfound parse error:', e.message); }
}
return result.length > 0 ? result : [];

