              posted_date: p.datePosted || new Date().toISOString(),
              tags: p.occupationalCategory || '',
              job_id: p.url || p.sameAs || ''
            }});
          }
        }
      } catch(pe) {}
    }
    // Also try extracting from __NEXT_DATA__ or similar React hydration patterns
    const nextDataMatch = html.match(/<script id=["']__NEXT_DATA__["'][^>]*>([\s\S]*?)<\/script>/);
    if (nextDataMatch) {
      try {
        const nd = JSON.parse(nextDataMatch[1]);
        const jobs = nd?.props?.pageProps?.jobs || [];
        for (const j of jobs) {
          result.push({ json: {
            job_title: j.title || j.job_title || '',
            company: j.company?.name || j.company_name || '',
            job_url: `https://www.workatastartup.com/jobs/${j.id || j.slug}`,
