const allItems = $input.all();

// Get existing jobs from the Google Sheets node
let existingUrls = new Set();
let existingKeys = new Set();
try {
  const sheetItems = $('Get Existing Raw Jobs').all();
  for (const si of sheetItems) {
    if (si.json.job_url) existingUrls.add(si.json.job_url.trim());
    const key = `${(si.json.company || '').trim().toLowerCase()}|${(si.json.job_title || '').trim().toLowerCase()}`;
    if (key !== '|') existingKeys.add(key);
  }
} catch(e) { console.log('Could not read existing sheet items, proceeding without dedup:', e.message); }

// Keywords filter - only process relevant job categories
const KEYWORD_FILTER = [
  'data analyst', 'data scientist', 'business intelligence', 'bi analyst',
  'marketing analyst', 'growth analyst', 'performance marketing',
  'ai marketing', 'ai automation', 'ai workflow', 'automation specialist',
  'martech', 'creative strategist', 'data engineer', 'analytics engineer',
  'product analyst', 'revenue analyst', 'insights analyst', 'reporting analyst',
  'machine learning', 'ml engineer', 'data manager', 'analytics manager'
];

const seenUrls = new Set();
const result = [];

for (const item of allItems) {
  const url = (item.json.job_url || '').trim();
  if (!url || url.length < 10) continue;
  if (existingUrls.has(url) || seenUrls.has(url)) continue;

  const companyKey = `${(item.json.company || '').trim().toLowerCase()}|${(item.json.job_title || '').trim().toLowerCase()}`;
  if (companyKey !== '|' && existingKeys.has(companyKey)) continue;

  // Keyword relevance check
  const titleLower = (item.json.job_title || '').toLowerCase();
  const descLower = (item.json.description || '').toLowerCase().substring(0, 500);
  const isRelevant = KEYWORD_FILTER.some(kw => titleLower.includes(kw) || descLower.includes(kw));

  // Also accept if it has async/remote keywords and passes basic checks
  const hasAsyncKeyword = ['async', 'asynchronous', 'worldwide remote', 'global remote', 'work from anywhere'].some(kw => descLower.includes(kw));

  if (!isRelevant && !hasAsyncKeyword) continue;

  seenUrls.add(url);
  result.push(item);
}

return result;

const items = $input.all();
const hardFilteredItems = $('Hard Taiwan Filter').all();
const result = [];

for (let i = 0; i < items.length; i++) {
  const aiResponseItem = items[i];
  // Match back to original job data
  const originalJob = hardFilteredItems[i]?.json || {};

  // Parse AI response
  let ai = {
    taiwan_eligible: 'unclear',
    reason: 'AI check unavailable',
    location_risk: 'medium',
    timezone_risk: 'medium',
    contractor_possible: 'unclear',
    decision: 'manual_check'
  };

  try {
    const content = aiResponseItem.json?.content?.[0]?.text || '';
    const jsonMatch = content.match(/\{[\s\S]*?\}/);
    if (jsonMatch) {
      const parsed = JSON.parse(jsonMatch[0]);
      ai = { ...ai, ...parsed };
    }
  } catch(e) {
    console.log('AI parse error:', e.message);
  }

  // Hard reject from AI
  if (ai.decision === 'reject' || ai.taiwan_eligible === 'no') {
    continue;
  }

  const desc = (originalJob.description || '').toLowerCase();
  const title = (originalJob.job_title || '').toLowerCase();
  const combined = desc + ' ' + title;

  // Async filter
  const ASYNC_POSITIVE = ['async', 'asynchronous', 'flexible hours', 'flexible schedule', 'own hours', 'own schedule', 'distributed team', 'remote-first', 'remote first', 'low meeting', 'work across time zones', 'timezone flexible', 'overlap not required'];
  const ASYNC_NEGATIVE = ['strict 9-to-5', 'strict 9 to 5', 'fixed us hours', 'fixed est hours', 'fixed pst hours', 'fixed cet hours', 'daily live calls required', 'must overlap full business day', 'must be available 9am-5pm', 'core hours 9am'];

  if (ASYNC_NEGATIVE.some(p => combined.includes(p))) continue;

  const asyncMatches = ASYNC_POSITIVE.filter(p => combined.includes(p));
  let asyncLevel = 'unknown';
  if (asyncMatches.includes('async') || asyncMatches.includes('asynchronous')) asyncLevel = 'high';
  else if (asyncMatches.length >= 2) asyncLevel = 'high';
  else if (asyncMatches.length === 1) asyncLevel = 'medium';

  // Role fit
  const ROLES = {
    data_analyst: ['data analyst', 'business intelligence analyst', 'bi analyst', 'marketing analyst', 'growth analyst', 'performance marketing analyst', 'revenue analyst', 'insights analyst', 'reporting analyst', 'product analyst'],
    data_scientist: ['data scientist', 'junior data scientist', 'ml engineer', 'machine learning engineer', 'analytics engineer'],
    ai_specialist: ['ai marketing', 'ai automation', 'ai workflow', 'automation specialist', 'martech analyst', 'marketing technology', 'ai specialist', 'ai consultant'],
    creative_data: ['creative strategist', 'content analyst', 'brand analyst', 'creative analyst']
  };

  let roleCategory = 'other';
  let roleFitScore = 0;

  for (const [cat, keywords] of Object.entries(ROLES)) {
    if (keywords.some(kw => title.includes(kw))) {
      roleCategory = cat;
      roleFitScore = 25;
      break;
    }
  }

  if (roleFitScore === 0) {
    const ADJACENT = ['analyst', 'analytics', 'data', 'marketing', 'growth', 'automation', 'intelligence', 'insights', 'researcher', 'strategist'];
    if (ADJACENT.some(kw => title.includes(kw))) {
      roleCategory = 'adjacent';
      roleFitScore = 15;
    }
  }

  if (roleFitScore === 0) continue; // Skip completely unrelated roles

  // Scoring
  let score = 0;

  // Taiwan eligibility (40 pts)
  if (ai.taiwan_eligible === 'yes' && ai.location_risk === 'low') score += 40;
  else if (ai.taiwan_eligible === 'yes') score += 30;
  else if (ai.decision === 'keep') score += 30;
  else if (ai.decision === 'manual_check') score += 20;

  // Async fit (25 pts)
  if (asyncLevel === 'high') {
    if (combined.includes('async') || combined.includes('asynchronous')) score += 25;
    else if (combined.includes('flexible hours') || combined.includes('flexible schedule')) score += 20;
    else if (combined.includes('distributed team')) score += 15;
    else score += 10;
  } else if (asyncLevel === 'medium') score += 10;

  // Role fit (25 pts)
  score += roleFitScore;

  // Salary fit (max 25 pts)
  const salaryText = (originalJob.salary || '').toLowerCase();
  let salaryScore = 0;
  if (salaryText) {
    salaryScore = 10;
    const numMatches = salaryText.match(/(\d[\d,\.]+)/);
    if (numMatches) {
      let n = parseFloat(numMatches[1].replace(/,/g, ''));
      if (salaryText.includes('k')) n *= 1000;
      // Detect if annual vs monthly
      const isAnnual = salaryText.includes('/yr') || salaryText.includes('/year') || salaryText.includes('annual') || n > 20000;
      const monthly = isAnnual ? n / 12 : n;
      if (monthly >= 5000) salaryScore = 25;
      else if (monthly >= 3000) salaryScore = 15;
    }
  }
  score += salaryScore;

  const whyFit = [];
  if (ai.taiwan_eligible === 'yes') whyFit.push('Taiwan-eligible');
  if (ai.contractor_possible === 'yes') whyFit.push('contractor-friendly');
  if (asyncLevel === 'high') whyFit.push('strongly async');
  else if (asyncLevel === 'medium') whyFit.push('flexible hours');
  if (roleCategory !== 'other') whyFit.push(roleCategory.replace(/_/g, ' '));
  if (salaryScore >= 15) whyFit.push('good salary');

  result.push({
    json: {
      ...originalJob,
      taiwan_eligible: ai.taiwan_eligible,
      taiwan_reason: ai.reason,
      location_risk: ai.location_risk,
      timezone_risk: ai.timezone_risk,
      contractor_possible: ai.contractor_possible,
      decision: ai.decision,
      async_level: asyncLevel,
      role_category: roleCategory,
      score,
      why_good_fit: whyFit.join(', '),
      date_found: new Date().toISOString().split('T')[0],
      application_status: 'new',
      notes: ''
    }
  });
}

return result;

const items = $input.all();
const highScoreItems = $('Score 85 Or Above').all();
const result = [];

for (let i = 0; i < items.length; i++) {
  const aiResp = items[i];
  const originalJob = highScoreItems[i]?.json || {};
  let coverLetter = '';
  try {
    coverLetter = aiResp.json?.content?.[0]?.text || '';
  } catch(e) {}
  result.push({ json: { ...originalJob, cover_letter: coverLetter, alert_sent: true } });
}
return result;

const items = $input.all();
const allJobs = items[0]?.json?.all_jobs || [];

if (!allJobs.length) {
  return [{ json: {
    subject: 'Daily Taiwan Jobs - No New Matches Today',
    body: 'No new Taiwan-eligible async remote jobs were found today that scored 70+.\n\nThe workflow ran successfully. Try again tomorrow!\n\n-- Daily Taiwan Eligible Async Remote Job Hunter'
  }}];
}

const sorted = [...allJobs].sort((a, b) => (b.score || 0) - (a.score || 0));
const topJobs = sorted.slice(0, 10);
const manualCheck = sorted.filter(j => j.decision === 'manual_check' && (j.score || 0) >= 80);
const highAlerts = sorted.filter(j => (j.score || 0) >= 85);

const date = new Date().toLocaleDateString('en-US', {
  timeZone: 'Asia/Taipei',
  weekday: 'long', year: 'numeric', month: 'long', day: 'numeric'
});

let body = `DAILY TAIWAN ELIGIBLE ASYNC REMOTE JOBS\n`;
body += `${date}\n`;
body += `${'='.repeat(50)}\n\n`;
body += `${sorted.length} new job(s) passed all filters today.`;
if (highAlerts.length > 0) body += ` ** ${highAlerts.length} INSTANT ALERT job(s) scored 85+! **`;
body += `\n\n`;

body += `TOP JOBS TODAY\n${'─'.repeat(50)}\n\n`;

topJobs.forEach((j, i) => {
  const score = j.score || 0;
  const flag = score >= 85 ? ' *** APPLY NOW ***' : score >= 75 ? ' ** High Priority **' : '';
  body += `${i + 1}. ${j.job_title || 'Untitled'}${flag}\n`;
  body += `   Company:          ${j.company || 'Unknown'}\n`;
  body += `   Score:            ${score}/100\n`;
  body += `   Taiwan eligible:  ${j.taiwan_eligible || 'unclear'}\n`;
  body += `   Reason:           ${j.taiwan_reason || 'N/A'}\n`;
  body += `   Async level:      ${j.async_level || 'unknown'}\n`;
  body += `   Timezone risk:    ${j.timezone_risk || 'unknown'}\n`;
  body += `   Location risk:    ${j.location_risk || 'unknown'}\n`;
  body += `   Contractor:       ${j.contractor_possible || 'unclear'}\n`;
  body += `   Salary:           ${j.salary || 'not listed'}\n`;
  body += `   Role category:    ${(j.role_category || 'N/A').replace(/_/g, ' ')}\n`;
  body += `   Why it fits Jerry: ${j.why_good_fit || 'N/A'}\n`;
  body += `   Source:           ${j.source || 'Unknown'}\n`;
  body += `   Apply link:       ${j.job_url || 'N/A'}\n`;
  if (j.cover_letter) body += `\n   [Cover letter draft ready - check sheet]\n`;
  body += `\n`;
});

if (manualCheck.length > 0) {
  body += `\nMANUAL CHECK NEEDED (high score, unclear eligibility)\n${'─'.repeat(50)}\n`;
  manualCheck.forEach((j, i) => {
    body += `${i + 1}. ${j.job_title} at ${j.company} (Score: ${j.score})\n`;
    body += `   Reason: ${j.taiwan_reason}\n`;
    body += `   Link: ${j.job_url}\n\n`;
  });
}

body += `\n${'='.repeat(50)}\n`;
body += `Sent by: Daily Taiwan Eligible Async Remote Job Hunter\n`;
body += `Full results + cover letter drafts: Taiwan Eligible Async Remote Jobs (Google Sheet)`;

const subjectFlag = highAlerts.length > 0 ? `APPLY NOW: ${highAlerts.length} top job(s) - ` : '';
return [{ json: {
  subject: `${subjectFlag}Daily Taiwan Jobs: ${sorted.length} match(es) | ${date}`,
  body,
  job_count: sorted.length,
  high_alert_count: highAlerts.length
}}];
